/**
 * A rejected native boundary operation.
 */
sealed class FfiSessionException: kotlin.Exception() {
    
    /**
     * Invalid host data, model operation or session state.
     */
    class Invalid(
        
        /**
         * Diagnostic without credentials or document contents.
         */
        val `reason`: kotlin.String
        ) : FfiSessionException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * A previous panic poisoned the serialization lock.
     */
    class Poisoned(
        ) : FfiSessionException() {
        override val message
            get() = ""
    }
    
    /**
     * The optional native storage executor is not configured in this build.
     */
    class StoreNotConfigured(
        ) : FfiSessionException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiSessionException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiSessionException = FfiConverterTypeFfiSessionError.lift(error_buf)
    }

    
}

