/**
 * Native FlushReply; fields retain their domain meaning.
 */
sealed class FlushReply {
    
    /**
     * All required updates were acknowledged.
     */
    object Drained : FlushReply()
    
    
    /**
     * Retained rows prevent successful draining.
     */
    data class NotDrained(
        /**
         * Number of retained undelivered rows.
         */
        val `undelivered`: kotlin.UInt) : FlushReply()
        
    {
        

        companion object
    }
    
    /**
     * No live connection is available.
     */
    object Offline : FlushReply()
    
    
    /**
     * Write authorization is absent.
     */
    object ReadOnly : FlushReply()
    
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFlushReply : FfiConverterRustBuffer<FlushReply>{
    override fun read(buf: ByteBuffer): FlushReply {
        return when(buf.getInt()) {
            1 -> FlushReply.Drained
            2 -> FlushReply.NotDrained(
                FfiConverterUInt.read(buf),
                )
            3 -> FlushReply.Offline
            4 -> FlushReply.ReadOnly
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FlushReply): ULong = when(value) {
        is FlushReply.Drained -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FlushReply.NotDrained -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUInt.allocationSize(value.`undelivered`)
            )
        }
        is FlushReply.Offline -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FlushReply.ReadOnly -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: FlushReply, buf: ByteBuffer) {
        when(value) {
            is FlushReply.Drained -> {
                buf.putInt(1)
                Unit
            }
            is FlushReply.NotDrained -> {
                buf.putInt(2)
                FfiConverterUInt.write(value.`undelivered`, buf)
                Unit
            }
            is FlushReply.Offline -> {
                buf.putInt(3)
                Unit
            }
            is FlushReply.ReadOnly -> {
                buf.putInt(4)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
